"use client";

import { useEffect, useState } from "react";
import { CARD_SURFACE } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import { highlightCode } from "@/features/code-block/code-block-highlight";
import {
  calloutLines,
  languageLook,
  normalizeLanguage,
} from "@/features/code-block/code-block-schema";
import type { CSSProperties } from "react";
import type {
  CodeLine,
  CodeToken,
} from "@/features/code-block/code-block-highlight";

/**
Past this many lines the block folds, showing the first FOLDED_LINES with a fade and a button for the rest.
*/
const FOLD_AFTER = 20;
const FOLDED_LINES = 14;
const COPIED_MS = 1600;

const ICON_BUTTON =
  "focus-visible:ring-ring text-muted-foreground hover:text-foreground hover:bg-background flex size-7 shrink-0 items-center justify-center rounded-md transition-colors outline-none focus-visible:ring-2 disabled:pointer-events-none disabled:opacity-40";

/**
What came back for one piece of code. A result for older code reads as not highlighted yet, so an edit never flashes stale colors.
*/
interface Highlighted {
  readonly key: string;
  readonly lines: CodeLine[] | null;
}

type TokenStyle = CSSProperties & {
  "--shiki-light"?: string;
  "--shiki-dark"?: string;
};

function tokenStyle(token: CodeToken): TokenStyle {
  return { "--shiki-dark": token.dark, "--shiki-light": token.light };
}

function splitLines(code: string): string[] {
  return code.replace(/\n$/u, "").split("\n");
}

// Inline icons, so the card installs without an icon library.
const CopyIcon = () => (
  <svg
    aria-hidden
    viewBox="0 0 24 24"
    className="size-3.5"
    fill="none"
    stroke="currentColor"
    strokeWidth={2}
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <rect width="14" height="14" x="8" y="8" rx="2" />
    <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" />
  </svg>
);

const CheckIcon = () => (
  <svg
    aria-hidden
    viewBox="0 0 24 24"
    className="size-3.5 text-emerald-600 dark:text-emerald-400"
    fill="none"
    stroke="currentColor"
    strokeWidth={2.5}
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M20 6 9 17l-5-5" />
  </svg>
);

function useCopy(text: string) {
  const [isCopied, setIsCopied] = useState(false);
  useEffect(() => {
    // Runs on every change; resetting an already-false flag is a no-op.
    const timer = setTimeout(() => setIsCopied(false), COPIED_MS);
    return () => clearTimeout(timer);
  }, [isCopied]);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
    } catch {
      setIsCopied(false);
    }
  };
  return { copy, isCopied };
}

/**
Shiki's tokens for the code, once the model has finished writing it. Highlighting every streamed chunk would re-run the grammar dozens of times a second, so streaming code stays plain.
*/
function useHighlighted(code: string, language: string, isStreaming: boolean) {
  const [result, setResult] = useState<Highlighted | null>(null);
  const key = `${language}\n${code}`;
  useEffect(() => {
    let isCancelled = false;
    const run = async () => {
      let lines: CodeLine[] | null;
      try {
        lines = await highlightCode(code.replace(/\n$/u, ""), language);
      } catch {
        lines = null;
      }
      if (!isCancelled) {
        setResult({ key, lines });
      }
    };
    if (!isStreaming && code) {
      run();
    }
    return () => {
      isCancelled = true;
    };
  }, [key, code, language, isStreaming]);
  return result?.key === key ? result.lines : null;
}

const CodeText = ({
  text,
  tokens,
}: {
  readonly text: string;
  readonly tokens: CodeLine | undefined;
}) => {
  if (!tokens) {
    return text;
  }
  return (
    <>
      {tokens.map((token, index) => (
        <span
          key={index}
          style={tokenStyle(token)}
          className="text-(--shiki-light) dark:text-(--shiki-dark)"
        >
          {token.text}
        </span>
      ))}
    </>
  );
};

/**
The model's cursor: a block that blinks at the end of the code while it is still being written.
*/
const Caret = () => (
  <span
    aria-hidden
    className="bg-foreground/70 ml-px inline-block h-[1.1em] w-[0.55em] animate-pulse align-text-bottom motion-reduce:animate-none"
  />
);

/**
A code block for chat replies: the code the model wrote, highlighted for its language, with its language, line numbers, called-out lines and a copy button.
*/
export default function CodeBlockCard({
  code = "",
  language,
  filename,
  highlight,
  streaming = false,
  className,
}: {
  readonly code?: string;
  readonly language?: string | null;
  /**
  The file the code belongs in; it names the code for the copy button.
  */
  readonly filename?: string | null;
  /**
  Line numbers (from 1) to call out.
  */
  readonly highlight?: readonly number[] | null;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  const [isExpanded, setIsExpanded] = useState(false);
  const lang = normalizeLanguage(language);
  const look = languageLook(lang);
  const lines = splitLines(code);
  const tokens = useHighlighted(code, lang, streaming);
  const callouts = calloutLines(highlight, lines.length);
  const { copy, isCopied } = useCopy(code);

  const canFold = !streaming && lines.length > FOLD_AFTER;
  const isFolded = canFold && !isExpanded;
  const shown = isFolded ? lines.slice(0, FOLDED_LINES) : lines;
  const gutter = `${String(lines.length).length + 1}ch`;
  const title = filename?.trim() || look.label;

  return (
    <figure
      aria-busy={streaming}
      className={cn(
        CARD_SURFACE,
        "col-span-full w-full max-w-2xl overflow-hidden rounded-2xl",
        className
      )}
    >
      <figcaption className="bg-muted/50 flex h-10 items-center justify-end gap-2 border-b pr-1.5 pl-3">
        {streaming ? (
          <span className="text-muted-foreground mr-auto text-xs">
            Writing…
          </span>
        ) : null}
        <span className="text-muted-foreground shrink-0 text-xs">
          {look.label}
        </span>
        <button
          type="button"
          disabled={streaming || !code}
          onClick={copy}
          aria-label={isCopied ? "Copied" : `Copy ${title}`}
          className={ICON_BUTTON}
        >
          {isCopied ? <CheckIcon /> : <CopyIcon />}
        </button>
        <span className="sr-only" aria-live="polite">
          {isCopied ? "Copied to clipboard" : ""}
        </span>
      </figcaption>

      <div className="relative">
        <pre className="overflow-x-auto py-3 font-mono text-[13px] leading-5">
          <code className="block w-max min-w-full">
            {shown.map((text, index) => {
              const number = index + 1;
              const isCallout = callouts.has(number);
              const isLast = streaming && number === lines.length;
              return (
                <span
                  // eslint-disable-next-line react-doctor/no-array-index-as-key -- a line's number is its identity: code lines never reorder
                  key={number}
                  className={cn(
                    "flex pr-4",
                    isCallout &&
                      "bg-amber-500/10 shadow-[inset_2px_0_0_var(--color-amber-500)]"
                  )}
                >
                  <span
                    aria-hidden
                    className={cn(
                      "shrink-0 pr-4 text-right tabular-nums select-none",
                      isCallout
                        ? "text-amber-700 dark:text-amber-400"
                        : "text-muted-foreground/60"
                    )}
                    style={{ width: `calc(${gutter} + 1rem)` }}
                  >
                    {number}
                  </span>
                  <span className="min-w-0">
                    <CodeText text={text} tokens={tokens?.[index]} />
                    {isLast ? <Caret /> : null}
                  </span>
                </span>
              );
            })}
          </code>
        </pre>
        {isFolded ? (
          <div
            aria-hidden
            className="from-background pointer-events-none absolute inset-x-0 bottom-0 h-16 bg-linear-to-t"
          />
        ) : null}
      </div>

      {canFold ? (
        <button
          type="button"
          aria-expanded={isExpanded}
          onClick={() => setIsExpanded((current) => !current)}
          className="focus-visible:ring-ring text-muted-foreground hover:text-foreground hover:bg-muted/50 w-full border-t py-2 text-xs transition-colors outline-none focus-visible:ring-2 focus-visible:ring-inset"
        >
          {isExpanded ? "Show less" : `Show all ${lines.length} lines`}
        </button>
      ) : null}
    </figure>
  );
}

import { z } from "zod";

export const codeBlockCatalogEntry = {
  description:
    "A code block: code you wrote for the user, highlighted for its language, with the file name, line numbers and a copy button. Use it whenever the reply includes code the user will read, paste or save: a function, a component, a config file, a query, a script. One block per file. Keep commands to run in a shell out of it (use the Terminal card for those). Explain the code in your sentence, not in long comments.",
  props: z.object({
    code: z
      .string()
      .describe(
        "The code itself, complete and ready to paste, with its own indentation and no Markdown fences."
      ),
    filename: z
      .string()
      .nullable()
      .describe(
        "The file the code belongs in, like app/page.tsx or docker-compose.yml. Null for a snippet that isn't a whole file."
      ),
    highlight: z
      .array(z.number())
      .nullable()
      .describe(
        "Line numbers (from 1) to call out, like the lines that changed or the ones the user asked about. Null for none."
      ),
    language: z
      .string()
      .describe(
        "The language for highlighting, like tsx, python, go, sql, yaml or json."
      ),
  }),
};

import type { BundledLanguage, Highlighter } from "shiki";

const THEMES = { dark: "github-dark", light: "github-light" } as const;

export interface CodeToken {
  readonly text: string;
  readonly light?: string;
  readonly dark?: string;
}

export type CodeLine = readonly CodeToken[];

/**
Shiki itself loads on the first code block, not with the page.
*/
async function loadShiki() {
  // eslint-disable-next-line import-x/dynamic-import-chunkname -- Turbopack names its own chunks; a webpack magic comment would do nothing
  return await import("shiki");
}

async function createCardHighlighter() {
  const { createHighlighter } = await loadShiki();
  return await createHighlighter({
    langs: [],
    themes: [THEMES.light, THEMES.dark],
  });
}

const shared: { highlighter?: Promise<Highlighter> } = {};

/**
One highlighter for the page, made on first use. Shiki loads each language's grammar only when a block asks for it, so a page of TypeScript never downloads Rust.
*/
function getHighlighter() {
  shared.highlighter ??= createCardHighlighter();
  return shared.highlighter;
}

/**
The code as lines of colored tokens, a light and a dark color each. Null when Shiki has no grammar for the language, so the card shows the code plain.
*/
export async function highlightCode(
  code: string,
  language: string
): Promise<CodeLine[] | null> {
  const { bundledLanguages } = await loadShiki();
  if (!Object.hasOwn(bundledLanguages, language)) {
    return null;
  }
  const lang = language as BundledLanguage;
  const highlighter = await getHighlighter();
  await highlighter.loadLanguage(lang);
  return highlighter
    .codeToTokensWithThemes(code, { lang, themes: THEMES })
    .map((line) =>
      line.map((token) => ({
        dark: token.variants.dark?.color,
        light: token.variants.light?.color,
        text: token.content,
      }))
    );
}

/**
How a language shows in the header: its name, and the dot GitHub's linguist colors it with, so a file reads at a glance the way it does on GitHub.
*/
interface LanguageLook {
  readonly label: string;
  readonly color: string;
}

const LOOKS: Record<string, LanguageLook> = {
  bash: { color: "#89e051", label: "Bash" },
  c: { color: "#555555", label: "C" },
  cpp: { color: "#f34b7d", label: "C++" },
  csharp: { color: "#178600", label: "C#" },
  css: { color: "#663399", label: "CSS" },
  diff: { color: "#8b949e", label: "Diff" },
  dockerfile: { color: "#384d54", label: "Dockerfile" },
  go: { color: "#00add8", label: "Go" },
  graphql: { color: "#e10098", label: "GraphQL" },
  html: { color: "#e34c26", label: "HTML" },
  java: { color: "#b07219", label: "Java" },
  javascript: { color: "#f1e05a", label: "JavaScript" },
  json: { color: "#8b949e", label: "JSON" },
  jsx: { color: "#f1e05a", label: "JSX" },
  kotlin: { color: "#a97bff", label: "Kotlin" },
  markdown: { color: "#083fa1", label: "Markdown" },
  php: { color: "#4f5d95", label: "PHP" },
  powershell: { color: "#012456", label: "PowerShell" },
  python: { color: "#3572a5", label: "Python" },
  ruby: { color: "#701516", label: "Ruby" },
  rust: { color: "#dea584", label: "Rust" },
  sql: { color: "#e38c00", label: "SQL" },
  svelte: { color: "#ff3e00", label: "Svelte" },
  swift: { color: "#f05138", label: "Swift" },
  text: { color: "#8b949e", label: "Text" },
  toml: { color: "#9c4221", label: "TOML" },
  tsx: { color: "#3178c6", label: "TSX" },
  typescript: { color: "#3178c6", label: "TypeScript" },
  vue: { color: "#41b883", label: "Vue" },
  yaml: { color: "#cb171e", label: "YAML" },
};

/**
What people and models write for a language, mapped to the name above.
*/
const ALIASES: Record<string, string> = {
  "c#": "csharp",
  "c++": "cpp",
  cs: "csharp",
  docker: "dockerfile",
  golang: "go",
  js: "javascript",
  md: "markdown",
  plaintext: "text",
  ps1: "powershell",
  py: "python",
  rb: "ruby",
  rs: "rust",
  sh: "bash",
  shell: "bash",
  ts: "typescript",
  txt: "text",
  yml: "yaml",
  zsh: "bash",
};

/**
A language name the card knows, or the lower-cased input when it doesn't (the highlighter may still know it).
*/
export function normalizeLanguage(language: string | null | undefined): string {
  const key = typeof language === "string" ? language.trim().toLowerCase() : "";
  return ALIASES[key] ?? (key || "text");
}

export function languageLook(language: string): LanguageLook {
  return LOOKS[language] ?? { color: "#8b949e", label: language };
}

/**
Line numbers to call out, kept to lines that exist, in order, without repeats.
*/
export function calloutLines(
  lines: readonly number[] | null | undefined,
  lineCount: number
): ReadonlySet<number> {
  return new Set(
    (lines ?? []).filter(
      (line) => Number.isSafeInteger(line) && line >= 1 && line <= lineCount
    )
  );
}

/**
The surface every data card shares: the page's own background and text, and one hairline border. Cards with their own shape (a seat map, a ticket stub) take just this.
*/
export const CARD_SURFACE = "bg-background text-foreground border";

/**
The whole frame of a plain data card: the shared surface with 1rem corners and 1rem of padding. Each card adds its own width.
*/
export const CARD_FRAME = `${CARD_SURFACE} rounded-2xl p-4`;
